"""Editorial background for each scene — written for this app, NOT book text.

CONTEXT[sceneId] = (spoken/visible background, [people ids])
The background is read aloud (in a different voice) before the passage and
shown above it, always labelled as an introduction so it can never be
mistaken for the translator's text.  Names follow the spellings used in the
张佳玮 translation.
"""

PEOPLE = {
 "hemingway": ("海明威（书中的“我”）", "写这些事时他二十出头，1921 年底带着新婚妻子从美国来到巴黎，先给加拿大《多伦多星报》当驻外记者，1924 年起辞职专心写小说，很穷。这本书是他三十多年后、去世前几年回忆写成的。妻子叫他“塔蒂”。"),
 "hadley": ("哈德莉", "海明威的第一任妻子，比他大八岁。书里的“我妻子”就是她，她叫他“塔蒂”。两人 1921 年结婚，1927 年离婚；全书可以看作海明威晚年写给她的一封迟到的情书。"),
 "bumby": ("邦比", "海明威和哈德莉的儿子约翰的小名，1923 年 10 月出生。"),
 "stein": ("格特鲁德·斯泰因", "美国作家、现代艺术收藏家，1903 年起定居巴黎，比海明威大二十五岁。她在弗勒吕斯路 27 号的家里挂满毕加索、塞尚和马蒂斯，是当时巴黎最有名的沙龙。她是海明威早期的导师，后来两人疏远。"),
 "toklas": ("斯泰因的“同伴”", "即爱丽丝·B. 托克拉斯，斯泰因的终身伴侣。海明威在书里始终不提她的名字，只说“她的同伴”或“她那位朋友”。"),
 "beach": ("西尔维娅·比奇", "美国人，1919 年在巴黎开了英文书店兼租书馆“莎士比亚书店”。她借书给穷作家、替他们收信，1922 年还自己出钱出版了乔伊斯的《尤利西斯》。海明威说没有人比她对他更好。"),
 "joyce": ("詹姆斯·乔伊斯", "爱尔兰作家，《尤利西斯》的作者，当时已是巴黎文坛最受敬重的人物，视力极差。妻子诺拉，儿子乔治，女儿露西娅。"),
 "pound": ("艾兹拉·庞德", "美国诗人，现代主义诗歌的推手，为人极慷慨，到处替有才华的朋友找钱、找发表的地方。海明威教他打拳，他教海明威写作。妻子多罗茜是画家。"),
 "lewis": ("温德姆·刘易斯", "英国画家、作家，庞德的朋友。海明威第一眼就讨厌他。"),
 "fitzgerald": ("斯科特·菲茨杰拉德", "美国小说家，1925 年两人相识时他二十八岁，刚出版《了不起的盖茨比》，比海明威有名得多，也富有得多。他酗酒，对妻子泽尔达又爱又怕。"),
 "zelda": ("泽尔达", "菲茨杰拉德的妻子，美国南方人，美丽、任性。海明威认为她嫉妒丈夫的写作，故意拉他去喝酒。1930 年起她多次精神崩溃。"),
 "chaplin": ("邓克·查普林", "菲茨杰拉德在普林斯顿的同学，有名的棒球投手，初次见面那晚与他同来。"),
 "pascin": ("帕辛", "朱尔斯·帕辛，保加利亚出生的画家，蒙帕纳斯最出名的浪荡子，以画女人体闻名，身边总有模特。1930 年在画室自杀。"),
 "chink": ("钦克", "埃里克·多尔曼-史密斯，爱尔兰人，英国陆军职业军官。海明威 1918 年在意大利养伤时与他结识，是他和哈德莉最好的朋友，三人一起徒步翻过阿尔卑斯山的圣伯纳山口。"),
 "walsh": ("厄尼斯特·沃尔什", "美国诗人，文学杂志《此季度》的编辑，患肺结核，自知不久于人世——所以那一章叫《被死神标记的人》。他私下向海明威许诺过杂志的一笔大奖。"),
 "shipman": ("埃文·希普曼", "年轻的美国诗人，穷，懂赛马，对名利毫不在意，是海明威很喜欢的朋友。"),
 "lavigne": ("拉维涅先生", "“图卢兹黑人饭店”的老板，海明威一家是他的常客。"),
 "obrien": ("奥布里恩", "爱德华·奥布里恩，美国编辑，每年编选《年度最佳短篇小说》。他破例收入了海明威当时尚未发表过的赛马小说。"),
 "georges": ("乔治", "里兹酒吧的酒保领班；菲茨杰拉德常来的年代，他还是这里的小听差。"),
 "ney": ("内伊元帅", "拿破仑手下的元帅，号称“勇者中的勇者”，从莫斯科撤退时率领后卫。1815 年在今天铜像所在的地方附近被枪决。"),
 "mike": ("迈克·沃德", "海明威的朋友，在银行的旅行柜台工作，是他把海明威带进了自行车赛的世界。"),
}

CONTEXT = {
 "cafe-des-amateurs-1": ("这是全书的开头，大约是 1922 年的深秋。海明威二十三岁，和新婚妻子哈德莉刚搬到拐角的勒姆瓦纳主教街，这一带当时是巴黎最穷的街区之一。他从自家楼下这家他并不喜欢的咖啡馆写起。", ["hemingway", "hadley"]),
 "74-cardinal-lemoine-1": ("一个春天的早晨，海明威在这栋楼三楼的公寓里趁妻子还没醒就开始写作，窗外是街上的声音。那几年他和哈德莉迷上了赌赛马，手头稍有一点钱就去赛马场。", ["hemingway", "hadley"]),
 "74-cardinal-lemoine-2": ("海明威刚从莎士比亚书店回来。店主西尔维娅·比奇不认识他，却让他先把书借走、有钱再付。他上楼把这个好消息告诉妻子哈德莉，她叫他“塔蒂”。结尾那句“没敲敲木头”是老年海明威的叹息：这段婚姻几年后就结束了。", ["hemingway", "hadley", "beach"]),
 "74-cardinal-lemoine-3": ("1922 年，名作家格特鲁德·斯泰因带着同伴回访海明威夫妇的小公寓。她坐在搁在地上的床边读这个年轻人的小说，对其中一篇有性描写的《在密歇根》下了判词，又教他有钱该买画而不是买衣服。", ["hemingway", "hadley", "stein", "toklas"]),
 "39-rue-descartes-1": ("为了有个安静地方写作，海明威在这家旧旅馆的顶楼另租了一间小屋。法国诗人魏尔伦 1896 年就死在这栋楼里。这一天又冷又下雨，他站在街对面盘算生一炉火要花多少钱，最后决定走去圣米歇尔广场的咖啡馆写。", ["hemingway"]),
 "place-saint-michel-1": ("紧接上一段：海明威冒雨从笛卡尔路走到这里，坐进一家暖和的咖啡馆写小说，故事的背景是他少年时的美国密歇根。写完后，他想到可以带妻子哈德莉离开阴冷的巴黎，到山里去过冬。", ["hemingway", "hadley"]),
 "place-saint-michel-2": ("这一段出自附录，是海明威生前没有收入正文的篇章。时间晚了几年：儿子邦比已经出生，一家人搬到了蒙帕纳斯的锯木厂楼上。平时照看邦比的是帮佣玛丽和她当过兵的丈夫“图东”。", ["hemingway", "bumby", "hadley"]),
 "27-rue-de-fleurus-1": ("1922 年，海明威夫妇第一次登门拜访格特鲁德·斯泰因。她的工作室里挂满了当时还没人看得懂的现代画，像一座私人美术馆。和她同住的那位“同伴”，书里始终没有写出名字。", ["hemingway", "hadley", "stein", "toklas"]),
 "27-rue-de-fleurus-2": ("“迷惘的一代”这个说法就出自这里。斯泰因的旧福特车送去修理，车行里一个打过一战的年轻修理工活儿干得不好，被老板训斥；她把老板那句话转送给了海明威和所有参过战的年轻人。海明威后来把它印在第一部长篇《太阳照常升起》的扉页上，心里却并不服气。", ["hemingway", "stein"]),
 "27-rue-de-fleurus-3": ("几年之后。海明威与斯泰因已经熟到可以随时登门。这个明媚的春日，他照常登门，在客厅等候时，无意间听见楼上传来一段他不该听到的对话。两人的友谊实际上就此结束。", ["hemingway", "stein", "toklas"]),
 "musee-du-luxembourg-1": ("那时这座博物馆专门陈列在世和近代画家的作品。海明威写完一天的东西，常绕到这里来看塞尚，想从画里学到怎么把小说写出他想要的那种分量。", ["hemingway"]),
 "musee-du-luxembourg-2": ("1924 年海明威辞掉记者工作专心写小说，稿子却卖不出去，家里很穷。他常对妻子说有人请他吃午饭，其实是省下一顿，空着肚子在卢森堡公园一带走上两小时。", ["hemingway"]),
 "place-saint-sulpice-1": ("接着上一段的“饥饿路线”：饿着肚子从卢森堡公园出来，要去莎士比亚书店，得挑一条闻不到饭菜香、看不见糕饼橱窗的路走。这条路经过的就是这个广场。", ["hemingway", "beach"]),
 "shakespeare-and-company-1": ("海明威刚到巴黎不久，买不起书。这家英文书店兼租书馆是美国人西尔维娅·比奇开的，他第一次进门时身上的钱连押金都不够。两人谈到的乔伊斯，那时正在等这家书店替他出版《尤利西斯》。", ["hemingway", "beach", "joyce"]),
 "shakespeare-and-company-2": ("1924 年前后，海明威已辞去记者工作，小说却一篇篇被退回。这天他没吃午饭，饿着肚子走到书店，西尔维娅一眼看出他瘦了，一边把信件和一笔德国杂志寄来的稿费交给他，一边劝他好好吃饭。", ["hemingway", "beach"]),
 "quai-de-la-tournelle-1": ("从海明威在勒姆瓦纳主教街的家一路下坡，就到塞纳河边。河岸石墙上一排排绿色铁箱是旧书摊，他在这里淘便宜的英文书，也和摆摊的女人成了朋友。", ["hemingway"]),
 "quai-des-grands-augustins-1": ("接着上一段，沿河往下游走。这一带的书摊常有左岸旅馆里的客人留下的英文书，海明威和另一位女摊主聊起这些书是从哪儿来的。", ["hemingway"]),
 "square-du-vert-galant-1": ("写完一天的东西，或者有事要想的时候，海明威就沿着河走到这座岛的尖端来看人钓鱼。钓上来的是一种叫鮈鱼的小鱼，整条油炸了吃。这一章以巴黎迟迟不来的春天收尾。", ["hemingway"]),
 "pont-du-carrousel-1": ("这天海明威和哈德莉刚旅行回来，赌赛马又赢了钱，先去吃了牡蛎和螃蟹，然后在暮色里穿过杜伊勒里花园往家走。两人想起好朋友钦克，想起三个人一起翻越阿尔卑斯山的日子。这是全书里他们最幸福的一个傍晚。", ["hemingway", "hadley", "chink"]),
 "michaud-1": ("紧接桥上那一段：两人过了河，走到这家他们平时吃不起的饭店门口。乔伊斯一家常在里面吃饭。海明威站在窗外，想弄明白自己感到的到底是哪一种饿；这一章结尾处的不安，是他多年后回望这段婚姻时才有的。", ["hemingway", "hadley", "joyce", "chink"]),
 "michaud-2": ("这是多年以后，大约 1930 年前后。菲茨杰拉德已是酗酒缠身的名作家，妻子泽尔达刚经历第一次精神崩溃。他约海明威在这里吃午饭，说有一件比什么都重要的事要问：泽尔达说过一句关于他身体的话，把他彻底击垮了。", ["hemingway", "fitzgerald", "zelda"]),
 "brasserie-lipp-1": ("紧接莎士比亚书店那一段：西尔维娅劝他去吃饭，他口袋里又刚有了稿费，于是快步走到这里。喝着啤酒，他想起 1922 年冬天的那场灾难：哈德莉带着他全部的手稿去瑞士找他，箱子在里昂车站被偷，几年的心血只剩下两篇。", ["hemingway", "hadley", "obrien"]),
 "deux-magots-1": ("诗人沃尔什曾在一顿饭上郑重其事地暗示，要把自己杂志的一笔大奖颁给海明威。很久以后，海明威在这条大道上遇到乔伊斯，两人到这家咖啡馆坐下，才发现同一个许诺沃尔什不止对一个人说过。", ["hemingway", "joyce", "walsh"]),
 "closerie-des-lilas-1": ("紧接斯泰因那句“你们是迷惘的一代”。海明威从她家出来，走回锯木厂楼上的家，路过丁香园门口的内伊元帅铜像，停下来喝了一杯啤酒，想着这位元帅，也想着斯泰因的话到底对不对。", ["hemingway", "stein", "ney", "hadley"]),
 "closerie-des-lilas-2": ("1924 年海明威一家搬到附近的锯木厂楼上，丁香园就成了他每天写作的地方。这一段是他给这家咖啡馆画的像：老诗人、蓄须的教授，还有胸前别着勋章、在一战里受了伤的人。", ["hemingway"]),
 "closerie-des-lilas-3": ("海明威每天早晨带着笔记本和铅笔来这里写小说，最怕有人打断。这一段先写他写得顺手时的状态，再写一个不识趣的熟人找上门来搭话——他承认自己不擅长控制脾气，开口就骂了回去。", ["hemingway"]),
 "closerie-des-lilas-4": ("1925 年春天，海明威在“澳洲犬”酒吧初识菲茨杰拉德，那晚对方喝到失态。几天后两人在这里的露台上再见面，菲茨杰拉德却像什么都没发生过。他刚出版《了不起的盖茨比》，邀海明威一起去里昂，把他丢在那里的汽车开回来。", ["hemingway", "fitzgerald", "zelda"]),
 "113-notre-dame-des-champs-1": ("1924 年起海明威一家住在这里：院子里是一家锯木厂，他们住楼上。这天他从同一条街上庞德的工作室走回来，房东太太告诉他有个年轻人来找过他。那是诗人埃文·希普曼，正在丁香园等他。", ["hemingway", "hadley", "pound", "shipman"]),
 "113-notre-dame-des-champs-2": ("1925 年，菲茨杰拉德常不打招呼就找上门来，有时已经喝了酒。这是其中一次，他带着年幼的女儿。", ["hemingway", "fitzgerald"]),
 "pound-studio-1": ("诗人庞德和妻子多罗茜就住在这条街上，离海明威家几分钟路。庞德想学拳击，海明威来教他。这天傍晚，庞德的英国朋友、画家温德姆·刘易斯也在场，站在一旁看。", ["hemingway", "pound", "lewis", "hadley", "stein"]),
 "negre-de-toulouse-1": ("一个春天的傍晚，海明威写了一整天，从锯木厂楼上的家出来散步，心情很好。他刚戒掉赌赛马，觉得自己颇有德行。这家饭店是他们一家常吃晚饭的地方，餐巾都存在店里。", ["hemingway", "lavigne"]),
 "le-dome-1": ("同一个傍晚，海明威继续沿蒙帕纳斯大道走到这里。画家帕辛带着两个给他当模特的姐妹坐在露台上，招呼他过去喝一杯。帕辛是这一带最出名的浪荡子；五年后他在画室里自杀，海明威在这一章的结尾想起了这件事。", ["hemingway", "pascin"]),
 "dingo-bar-1": ("1925 年 4 月底，《了不起的盖茨比》出版才两个星期。还没什么名气的海明威正在这家酒吧喝酒，已经成名的菲茨杰拉德带着大学同学邓克·查普林走进来，作了自我介绍。这是美国文学史上最有名的一次初见，过程却相当尴尬。", ["hemingway", "fitzgerald", "chaplin"]),
 "14-rue-de-tilsitt-1": ("1925 年，海明威和菲茨杰拉德刚一起去里昂取回了车，那趟旅行一路都是麻烦。回来后，菲茨杰拉德请海明威夫妇到他租的公寓，同妻子泽尔达和小女儿一起吃午饭。", ["hemingway", "hadley", "fitzgerald", "zelda"]),
 "ritz-bar-1": ("时间一下子跳到二战之后的五十年代。菲茨杰拉德早已去世，海明威成了世界闻名的老作家。酒保领班乔治当年只是这里的小听差，他问海明威：大家都在打听的那位菲茨杰拉德先生，到底是谁？", ["hemingway", "georges", "fitzgerald"]),
 "auteuil-1": ("海明威和哈德莉起初只是偶尔赌赌赛马，后来他一个人越陷越深，把研究马和赛道当成了一份全职工作。奥特伊是障碍赛的赛场。不久之后他就下决心戒掉了。", ["hemingway"]),
 "vel-dhiv-1": ("戒掉赌赛马以后，朋友迈克·沃德带海明威去看自行车赛。场地赛、公路赛、六日赛，他一下子迷上了，却承认自己始终没能把它写好。文中的“冬季赛车场”就在这里，1959 年已经拆除。", ["hemingway", "mike"]),
}
